/* Optional offline test adapter: active only with ?demo=1, never by default. */
(function () {
  "use strict";
  // A browser demo must never replace an injected iCUE provider.
  if (window.plugins && window.plugins.Mediadataprovider) return;
  if (!window.__EDGE_DEMO_OVERRIDE__ && new URLSearchParams(location.search).get("demo") !== "1") return;
  function makeSignal() {
    const listeners = [];
    return {
      connect(callback) { listeners.push(callback); },
      emit(...args) { for (const callback of listeners) callback(...args); },
    };
  }
  const songs = [{"songName":"Midnight Current","artist":"Demo Artist","album":"Offline Preview • Vol. 1","thumbnail":"data:image/png;base64,"},{"songName":"A New Momentum","artist":"Demo Band","album":"Offline Preview • Vol. 2","thumbnail":"data:image/png;base64,"},{"songName":"First Light","artist":"Example Music","album":"Offline Preview • Vol. 3","thumbnail":"data:image/png;base64,"}];
  let index = 0;
  let playing = true;
  const media = {};
  for (const field of ["songName", "artist", "album", "thumbnail", "isPlaying"]) {
    media[field + "Changed"] = makeSignal();
  }
  media.asyncResponse = makeSignal();
  Object.defineProperties(media, {
    songName: { get: () => songs[index].songName },
    artist: { get: () => songs[index].artist },
    album: { get: () => songs[index].album },
    thumbnail: { get: () => songs[index].thumbnail },
    isPlaying: { get: () => playing },
  });
  for (const [property, method] of Object.entries({
    songName: "getSongName", artist: "getArtist", album: "getAlbum",
    thumbnail: "getThumbnail", isPlaying: "getIsPlaying",
  })) {
    media[method] = function (requestId) {
      setTimeout(() => media.asyncResponse.emit(requestId, media[property]), 15);
    };
  }
  function changeTrack(delta) {
    index = (index + delta + songs.length) % songs.length;
    for (const field of ["songName", "artist", "album", "thumbnail"]) {
      media[field + "Changed"].emit();
    }
  }
  media.triggerPlayPause = function () {
    playing = !playing;
    media.isPlayingChanged.emit();
  };
  media.triggerPreviousTrack = function () { changeTrack(-1); };
  media.triggerNextTrack = function () { changeTrack(1); };
  window.plugins = Object.assign({}, window.plugins, { Mediadataprovider: media });
  window.pluginMediadataprovider_initialized = true;
  window.iCUE_initialized = true;
  window.accentColor = "#22D3EE";
  window.backgroundColor = "#070B16";
})();
